from lab import *
assert cmd(['docker','inspect','--format','{{index .Config.Labels "eva.sesiune"}}',AP])=='eva-contab-codex-a05r8'
assert sql("SELECT count(*) FROM adempiere.ad_scheduler WHERE isactive='Y'")=='0'
t=auth('GardenAdmin',11,102,11);report={'utc':now(),'scenarios':{}}
def add(id,route,s,expected):report['scenarios'][id]={'route':route,'expected':expected,'sql':s,'observed':rows(s)};save('extra_native.json',report)
add('T323-R2-004','M_Locator existing + native T326 fixture','SELECT w.m_warehouse_id,w.value,count(l.m_locator_id) FROM adempiere.m_warehouse w JOIN adempiere.m_locator l USING(m_warehouse_id) WHERE w.ad_client_id=11 AND l.isactive=\'Y\' GROUP BY 1,2 HAVING count(*)>=2 ORDER BY 1','at least one test warehouse with three locators')
add('T163-R2-031','AD_Process exact production/reactivation exclusion',"SELECT ad_process_id,value,classname FROM adempiere.ad_process WHERE isactive='Y' AND (lower(classname) LIKE '%amerp%' OR lower(value) LIKE '%amer%') AND (lower(value||' '||classname) LIKE '%produc%') AND (lower(value||' '||classname) LIKE '%react%') ORDER BY 1",'0 registered/process active for production; broader payroll etc negative control in separate evidence')
add('T329-R2-003','M_AttributeSet in GardenWorld after actual lot tests',"SELECT ad_client_id,m_attributeset_id,islot,isguaranteedate,isserno,isinstanceattribute,mandatorytype FROM adempiere.m_attributeset WHERE ad_client_id=11 AND description='EVA-P01.T329-LOT' ORDER BY 2",'unique appropriate set; record was fixture-generated if already provisioned in T354 and not proof of two stock boots')
add('T329-R2-006','information_schema and pg_indexes as installed',"SELECT indexname,indexdef FROM pg_indexes WHERE schemaname='adempiere' AND tablename IN ('eva_stratstoc','eva_stratmiscare') ORDER BY 1",'client+product+warehouse+ASI index; full legacy backfill not asserted from empty legacy dataset')
add('T329-R2-028','M_Lot and corresponding M_AttributeSetInstance',"SELECT l.m_lot_id,l.m_product_id,l.name,asi.m_attributesetinstance_id,asi.guaranteedate::date FROM adempiere.m_lot l JOIN adempiere.m_attributesetinstance asi USING(m_lot_id) WHERE l.ad_client_id=11 AND l.created>=date '2026-11-02' ORDER BY 1,4",'MLot created and correlated to ASI; compare exact task target against synthetic alias')
add('T326-R2-023','Actual document/staging readback at run boundary',"SELECT s.eva_nrcomanda,l.eva_comandasite_id,l.m_inout_id,io.docstatus,l.ad_pinstance_id,pi.result,l.m_locator_id,l.eva_cantitate FROM adempiere.eva_linieculegere l JOIN adempiere.eva_comandasite s USING(eva_comandasite_id) JOIN adempiere.m_inout io ON l.m_inout_id=io.m_inout_id JOIN adempiere.ad_pinstance pi ON l.ad_pinstance_id=pi.ad_pinstance_id WHERE l.ad_client_id=11 AND s.eva_sursa='T203SRC' ORDER BY l.eva_linieculegere_id",'actual staged source; C_Order + shipment + AD_PInstance.Result=1 + line count/locator')
add('T326_inventory_S7','Install schema current static table columns - no simulated print/delta',"SELECT table_name,count(*) FROM information_schema.columns WHERE table_schema='adempiere' AND table_name IN ('eva_linieculegere','eva_miscarewms','eva_stocwms') GROUP BY 1 ORDER BY 1",'existence plus SQL schema; second boot/read measured only if actually performed')
add('T354-R2-003','Actual native set fixtures with left counts (including all names and no-stocks)',"SELECT p.m_product_id,p.value,p.isbom,p.isstocked,(SELECT count(*) FROM adempiere.m_storageonhand h WHERE h.m_product_id=p.m_product_id AND h.ad_client_id=11),(SELECT count(*) FROM adempiere.m_transaction tr WHERE tr.m_product_id=p.m_product_id AND tr.ad_client_id=11) FROM adempiere.m_product p WHERE p.ad_client_id=11 AND p.value LIKE 'T354-%' AND p.isstocked='N' AND p.isbom='Y' ORDER BY 1",'zero M_StorageOnHand/Transaction for every set, independent audit read; map to original scenarios via logs')
add('T354-R2-012','Actual pick/confirm effects in isolated staged site wave',"SELECT c.eva_nrcomanda,c.eva_comandasite_id,c.c_order_id,io.m_inout_id,io.docstatus,pc.m_inoutconfirm_id,pc.docstatus,c.c_invoice_id FROM adempiere.eva_comandasite c JOIN adempiere.m_inout io USING(c_order_id) JOIN adempiere.m_inoutconfirm pc ON pc.m_inout_id=io.m_inout_id WHERE c.ad_client_id=11 AND c.eva_sursa='T354SRC' ORDER BY 1",'PC CO plus shipment CO in same original fixture; do not credit checkout')
add('T331-R2-002','Native facts linked to operational EVA movement or stock tables, company 11',"SELECT t.tablename,count(f.fact_acct_id) FROM adempiere.ad_table t LEFT JOIN adempiere.fact_acct f ON f.ad_table_id=t.ad_table_id AND f.ad_client_id=11 WHERE t.tablename IN ('EVA_MiscareWms','EVA_StocWms') GROUP BY t.tablename ORDER BY 1",'zero Facts directly on each operational table; no attributed movements if no WMS operation in this isolated clone')
print('readbacks',len(report['scenarios']))
